import math

def heat_params(r, sigma):
    """Return (k, alpha, beta)."""
    k = 2 * r / sigma ** 2
    return k, -(k - 1) / 2, -(k + 1) ** 2 / 4

def to_heat(S, t, K, sigma, T):
    """Return (x, tau): log moneyness and variance time."""
    return math.log(S / K), 0.5 * sigma ** 2 * (T - t)

def price_from_u(u, S, K, r, sigma, t, T):
    """V = K * exp(alpha * x + beta * tau) * u."""
    k, alpha, beta = heat_params(r, sigma)
    x, tau = to_heat(S, t, K, sigma, T)
    return K * math.exp(alpha * x + beta * tau) * u
